<?php require 'autorizare.php';if(isset($_POST['sterge'])){$s=$pdo->prepare('DELETE FROM comentarii WHERE id_comentariu=?');$s->execute([(int)$_POST['sterge']]);}$rows=$pdo->query('SELECT co.id_comentariu,co.nume_utilizator,co.adresa_email,co.comentariu,c.titlu FROM comentarii co JOIN carti c ON c.id_carte=co.id_carte ORDER BY co.id_comentariu DESC')->fetchAll();include 'admin_top.php';?><table border="1" cellpadding="5"><tr><th>Carte</th><th>Utilizator</th><th>Comentariu</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['titlu'])?></td><td><?=h($r['nume_utilizator'])?><br><?=h($r['adresa_email'])?></td><td><?=nl2br(h($r['comentariu']))?></td><td><form method="post"><button name="sterge" value="<?=(int)$r['id_comentariu']?>">Sterge</button></form></td></tr><?php endforeach;?></table></body></html>
